```javascript
import * as THREE from 'three/webgpu';
import { color, uniform } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  if (config.scenePosition) {
    group.position.fromArray(config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.fromArray(config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.fromArray(config.sceneScale);
  }

  // Design constants
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const PAD = 0.5;
  const HDR_H = 0.08;
  const CTA_W = 1.4;
  const CTA_H = 0.36;

  // Color palette
  const cols = {
    surf: '#16161d',
    border: '#2a2a33',
    hairline: '#23232b',
    accent: '#ff2a38',
    text: '#e8ecf2',
    textMute: '#9a9aa0',
    ctaText: '#16161d'
  };

  // Main card background plane
  const cardGeom = new THREE.PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new THREE.MeshBasicNodeMaterial();
  cardMat.colorNode = color(new THREE.Color(cols.surf));
  const card = new THREE.Mesh(cardGeom, cardMat);
  group.add(card);

  // Border hairline
  const borderPts = [
    new THREE.Vector3(-CARD_W / 2, CARD_H / 2, 0.001),
    new THREE.Vector3(CARD_W / 2, CARD_H / 2, 0.001),
    new THREE.Vector3(CARD_W / 2, -CARD_H / 2, 0.001),
    new THREE.Vector3(-CARD_W / 2, -CARD_H / 2, 0.001),
    new THREE.Vector3(-CARD_W / 2, CARD_H / 2, 0.001)
  ];
  const borderGeom = new THREE.BufferGeometry().setFromPoints(borderPts);
  const borderMat = new THREE.LineBasicMaterial({ color: cols.border, linewidth: 1 });
  group.add(new THREE.Line(borderGeom, borderMat));

  // Header strip (machined metal with specular properties)
  const hdrGeom = new THREE.PlaneGeometry(CARD_W, HDR_H);
  const hdrMat = new THREE.MeshStandardNodeMaterial();
  hdrMat.colorNode = color(new THREE.Color(cols.surf));
  hdrMat.metalness = uniform(0.5);
  hdrMat.roughness = uniform(0.55);
  hdrMat.clearcoat = uniform(0.2);
  const hdr = new THREE.Mesh(hdrGeom, hdrMat);
  hdr.position.y = CARD_H / 2 - HDR_H / 2;
  hdr.position.z = 0.001;
  group.add(hdr);

  // Text creation helper
  const createText = (txt, style) => {
    if (!txt || !ctx) return null;
    try {
      if (typeof ctx.fontAtlas === 'function') return ctx.fontAtlas(txt, style);
      if (ctx.fontAtlas?.createText) return ctx.fontAtlas.createText(txt, style);
      if (ctx.createText) return ctx.createText(txt, style);
    } catch (e) {
      console.warn('Text creation failed:', txt, e);
    }
    return null;
  };

  const textList = [];
  let y = CARD_H / 2 - HDR_H - PAD;

  // Tier name
  const tierTxt = createText(config.textContent?.tierName || 'ATELIER RESERVE', {
    font: 'JetBrains Mono',
    fontSize: 20,
    fontWeight: 700,
    color: cols.text
  });
  if (tierTxt) {
    tierTxt.position.set(-CARD_W / 2 + PAD, y - 0.15, 0.002);
    group.add(tierTxt);
    textList.push(tierTxt);
  }
  y -= 0.35;

  // Price (in accent red)
  const priceTxt = createText(config.textContent?.price || '$480', {
    font: 'Lora',
    fontSize: 62,
    fontWeight: 600,
    color: cols.accent
  });
  if (priceTxt) {
    priceTxt.position.set(-CARD_W / 2 + PAD, y - 0.4, 0.002);
    group.add(priceTxt);
    textList.push(priceTxt);
  }
  y -= 0.8;

  // Caption
  const captionTxt = createText(config.textContent?.caption || 'PER MONTH, BILLED ANNUALLY', {
    font: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    color: cols.textMute
  });
  if (captionTxt) {
    captionTxt.position.set(-CARD_W / 2 + PAD, y - 0.06, 0.002);
    group.add(captionTxt);
    textList.push(captionTxt);
  }
  y -= 0.5;

  // Feature rows with hairline separators
  const feats = config.textContent?.features || [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];
  const featTxts = [];

  feats.forEach((feat, i) => {
    const txt = createText(feat, {
      font: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      color: cols.text
    });
    if (txt) {
      txt.position.set(-CARD_W / 2 + PAD, y - 0.19, 0.002);
      txt.userData.isFeature = true;
      group.add(txt);
      featTxts.push(txt);
    }

    y -= 0.375;

    if (i < feats.length - 1) {
      const hairlineGeom = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(-CARD_W / 2 + PAD, y, 0.0015),
        new THREE.Vector3(CARD_W / 2 - PAD, y, 0.0015)
      ]);
      const hairlineMat = new THREE.LineBasicMaterial({ color: cols.hairline, linewidth: 1 });
      group.add(new THREE.Line(hairlineGeom, hairlineMat));
      y -= 0.006;
    }
  });

  // CTA button (accent gradient with emissive glow)
  const ctaGeom = new THREE.PlaneGeometry(CTA_W, CTA_H);
  const ctaMat = new THREE.MeshBasicNodeMaterial();
  ctaMat.colorNode = color(new THREE.Color(cols.accent));
  ctaMat.emissive = uniform(new THREE.Color(cols.accent));
  ctaMat.emissiveIntensity = uniform(1.5);
  const ctaBtn = new THREE.Mesh(ctaGeom, ctaMat);
  ctaBtn.position.set(0, -CARD_H / 2 + PAD + CTA_H / 2, 0.001);
  ctaBtn.userData.isInteractive = true;
  group.add(ctaBtn);

  // CTA label text
  const ctaLblTxt = createText(config.textContent?.ctaLabel || 'JOIN THE RESERVE', {
    font: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    color: cols.ctaText
  });
  if (ctaLblTxt) {
    ctaLblTxt.position.set(0, ctaBtn.position.y, 0.003);
    group.add(ctaLblTxt);
  }

  // Animation timeline
  const timeline = gsap.timeline({ paused: false });
  const timelines = [];

  // Card mount: weighted-settle (scale 1.04 -> 1.0, power4.out, 900ms)
  gsap.set(group.scale, { x: 1.04, y: 1.04, z: 1.04 });
  const settleAnim = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
    paused: true
  });
  timeline.add(settleAnim, 0);
  timelines.push(settleAnim);

  // Feature rows: fade-up with stagger (opacity 0 -> 1, y +0.2 -> 0, 500ms, power2.out, 80ms stagger)
  if (featTxts.length > 0) {
    gsap.set(featTxts, { opacity: 0, y: 0.2 });
    const fadeUpAnim = gsap.to(featTxts, {
      opacity: 1,
      y: 0,
      duration: 0.5,
      ease: 'power2.out',
      stagger: 0.08,
      paused: true
    });
    timeline.add(fadeUpAnim, 0.2);
    timelines.push(fadeUpAnim);
  }

  // CTA press-down effect
  let ctaPressAnim = null;

  group.userData.handlers = {
    ctaMouseDown: () => {
      if (ctaPressAnim) ctaPressAnim.kill();
      ctaPressAnim = gsap.to(ctaBtn.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      });
    },
    ctaMouseUp: () => {
      if (ctaPressAnim) ctaPressAnim.kill();
      ctaPressAnim = gsap.to(ctaBtn.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out'
      });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    timeline.kill();
    if (ctaPressAnim) ctaPressAnim.kill();
    timelines.forEach(t => t.kill());

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
